// Builds a srcset string from the width variants generated by
// `npm run images` (scripts/generate-image-variants.mjs). Pure (no JSON import)
// so the build config and the tests can use it too; src/lib/responsive.js wraps
// it with the real manifest for components.
//
//   variants: { [webPath]: { w, h, widths: [...] } }
//   ext:      the file family to build: "webp" (the default) or "avif"
export function buildSrcSet(src, variants, ext = 'webp') {
  const meta = variants[src]
  if (!meta || meta.widths.length === 0) return undefined
  const stem = src.replace(/\.webp$/i, '')
  return [
    ...meta.widths.map((w) => `${stem}-${w}w.${ext} ${w}w`),
    `${stem}.${ext} ${meta.w}w`,
  ].join(', ')
}
